import {
  defaultAgentSpec,
  isAgentSpecEmpty,
  type AgentSpec,
} from "./agent-spec";
import { resolveMemoryTemplates, type SwarmMemoryState } from "./swarm-memory";

export function buildAgentRuntimePrompt(
  spec: AgentSpec,
  memoryState?: SwarmMemoryState,
  agentIndex?: number
): string {
  const isMultiAgent =
    spec.agents && spec.agents.length > 0 && agentIndex !== undefined;
  const subAgent =
    isMultiAgent && spec.agents ? spec.agents[agentIndex!] : undefined;

  const agentName = spec.name;
  const agentRole = subAgent ? subAgent.role : spec.persona.role;
  const agentTone = spec.persona.tone || "Helpful and clear";
  const agentInstructions = subAgent
    ? resolveMemoryTemplates(subAgent.instructions, memoryState ?? {})
    : resolveMemoryTemplates(spec.instructions, memoryState ?? {});

  const toolsSection =
    spec.tools.length > 0
      ? `\n\nAvailable capabilities:\n${spec.tools.map((t) => `- ${t.name} (${t.type.replace("_", " ")})`).join("\n")}\n\nNote: This is a preview session — external tools are not live. If a task would use a tool, explain your approach and provide the best answer you can from context.`
      : "";

  const swarmSection =
    !subAgent && spec.agents && spec.agents.length > 0
      ? `\n\nYou may coordinate sub-agents with these roles:\n${spec.agents.map((a) => `- ${a.role}: ${a.instructions}`).join("\n")}`
      : "";

  const memorySection = buildMemorySection(spec, memoryState, subAgent?.memory);

  return `You are ${agentName}, an AI agent deployed for end users.

## Persona
- Role: ${agentRole}
- Tone: ${agentTone}

## Instructions
${agentInstructions}
${toolsSection}${swarmSection}${memorySection}

Stay fully in character. You are speaking with an end user — not a developer. Be helpful, concise, and true to your defined tone.`;
}

function buildMemorySection(
  spec: AgentSpec,
  state: SwarmMemoryState | undefined,
  agentMemory?: { reads: string[]; writes: string[] }
): string {
  if (!spec.swarmMemory?.length || !state) return "";
  if (!agentMemory && !(state && Object.keys(state).length > 0)) return "";

  const reads = agentMemory?.reads ?? [];
  const writes = agentMemory?.writes ?? [];

  const lines = spec.swarmMemory.map((mk) => {
    const value = state[mk.key];
    const displayValue =
      value === undefined || value === null
        ? "(empty)"
        : typeof value === "string"
          ? `"${value.slice(0, 120)}${value.length > 120 ? "…" : ""}"`
          : JSON.stringify(value).slice(0, 120);

    const access = reads.includes(mk.key)
      ? " [you READ this]"
      : writes.includes(mk.key)
        ? " [you WRITE this]"
        : "";

    return `- ${mk.key} (${mk.type}): ${displayValue}${access}`;
  });

  const writeInstruction =
    writes.length > 0
      ? "\n\nWhen you write to memory, call the writeMemory tool with key-value pairs for the keys you own."
      : "";

  return `\n\n## Shared Memory (current state)\n${lines.join("\n")}${writeInstruction}`;
}

