import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  generateText,
  streamText,
  type UIMessage,
} from "ai";
import { z } from "zod";
import { agentSpecSchema, defaultAgentSpec, type SwarmAgent } from "@/lib/agent-spec";
import { buildAgentRuntimePrompt } from "@/lib/agent-prompt";
import { deepseekChat } from "@/lib/deepseek";
import type { SwarmUIMessage } from "@/lib/chat-types";
import {
  applyMemoryWrite,
  type SwarmMemoryState,
} from "@/lib/swarm-memory";

export const maxDuration = 30;

function topoSort(agents: SwarmAgent[]): SwarmAgent[] {
  const byId = new Map(agents.map((a) => [a.id, a]));
  const result: SwarmAgent[] = [];
  const visited = new Set<string>();

  function visit(id: string) {
    if (visited.has(id)) return;
    visited.add(id);
    const agent = byId.get(id);
    if (!agent) return;
    for (const dep of agent.dependsOn) {
      visit(dep);
    }
    result.push(agent);
  }

  for (const agent of agents) {
    visit(agent.id);
  }

  return result;
}

export async function POST(req: Request) {
  try {
    if (!process.env.DEEPSEEK_API_KEY) {
      return Response.json(
        { error: "DEEPSEEK_API_KEY is not set. Add it to .env.local." },
        { status: 500 }
      );
    }

    const body = await req.json();
    const messages: UIMessage[] = body.messages ?? [];
    const parsedSpec = agentSpecSchema.safeParse(body.agentSpec);
    const spec = parsedSpec.success ? parsedSpec.data : defaultAgentSpec;
    let memoryState: SwarmMemoryState = body.swarmMemoryInitial ?? {};

    const modelMessages = await convertToModelMessages(messages);
    const hasMultiAgent = Boolean(spec.agents?.length);

    const stream = createUIMessageStream<SwarmUIMessage>({
      execute: async ({ writer }) => {
        if (!hasMultiAgent) {
          const result = streamText({
            model: deepseekChat,
            system: buildAgentRuntimePrompt(
              spec,
              Object.keys(memoryState).length > 0 ? memoryState : undefined
            ),
            messages: modelMessages,
          });
          writer.merge(result.toUIMessageStream());
          return;
        }

        const agents = topoSort(spec.agents!);

        for (let i = 0; i < agents.length; i++) {
          const agent = agents[i];
          const agentIndex = spec.agents!.indexOf(agent);

          const writeMemoryTool = {
            description: "Write values to shared swarm memory so other agents can read them.",
            parameters: z.object({
              writes: z.record(z.unknown()),
            }),
            execute: async ({ writes }: { writes: Record<string, unknown> }) => {
              memoryState = applyMemoryWrite(memoryState, writes);
              return { success: true };
            },
          };

          const result = await generateText({
            model: deepseekChat,
            system: buildAgentRuntimePrompt(spec, memoryState, agentIndex),
            messages: modelMessages,
            tools: { writeMemory: writeMemoryTool },
            maxSteps: 3,
          });

          const writtenKeys = Object.keys(
            result.steps.flatMap((s) =>
              s.toolResults
                .filter((tr) => tr.toolName === "writeMemory")
                .flatMap((tr) =>
                  Object.keys((tr.args as { writes: Record<string, unknown> }).writes ?? {})
                )
            ).reduce(
              (acc, k) => ({ ...acc, [k]: true }),
              {} as Record<string, boolean>
            )
          );

          const writesForEvent = writtenKeys.map((key) => ({
            key,
            agentRole: agent.role,
          }));

          writer.write({
            type: "data-memoryState",
            id: `memory-${agent.id}`,
            data: { state: memoryState, writes: writesForEvent },
          });

          const label = `**[${agent.role}]**\n\n`;
          const separator = i < agents.length - 1 ? "\n\n---\n\n" : "";

          writer.write({
            type: "text-delta",
            textDelta: label + result.text + separator,
          });
        }
      },
      onError: (error) => {
        console.error("Preview stream error:", error);
        return error instanceof Error
          ? error.message
          : "An error occurred while running the preview.";
      },
    });

    return createUIMessageStreamResponse({ stream });
  } catch (error) {
    console.error("Preview route error:", error);
    return Response.json(
      {
        error:
          error instanceof Error
            ? error.message
            : "Failed to process preview request.",
      },
      { status: 500 }
    );
  }
}

