  const toolsList =
    spec.tools.length > 0
      ? spec.tools.map((t) => `- **${t.name}** (\`${t.type}\`)`).join("\n")
      : "_No tools configured._";

  const instructions = annotateMemoryTemplates(spec.instructions || "_No instructions yet._");

